const r=await Promise.allSettled([
 tools.exec_command({cmd:"python3 - <<'PY'
import pathlib,json,collections,os
root=pathlib.Path.home()/'.codex/sessions'
paths=sorted(root.rglob('*.jsonl'),key=lambda p:p.stat().st_mtime,reverse=True)
wanted={'CommandExecution','FileChange','McpToolCall','Extension','ImageView','UserMessage','AgentMessage','Reasoning','ContextCompaction','DynamicToolCall'}
events={'task_started','task_complete','turn_aborted','thread_settings_applied','item_completed'}
counts=collections.Counter(); schemas={}; examples={}; files=[]
def shape(x,depth=0):
 if isinstance(x,dict):return {k:shape(v,depth+1) if depth<3 else type(v).__name__ for k,v in x.items()}
 if isinstance(x,list):return ['count='+str(len(x))]+([shape(x[0],depth+1)] if x else [])
 return type(x).__name__
for p in paths:
 with p.open() as f:
  first=f.readline()
  try:meta=json.loads(first)
  except:continue
  if meta.get('type')!='session_meta' or meta.get('payload',{}).get('cli_version')!='0.166.0':continue
  files.append(str(p))
  for n,line in enumerate([first]+f.readlines(),1):
   try:x=json.loads(line)
   except:continue
   t=x.get('type'); d=x.get('payload') or {}
   key=t+':'+str(d.get('type',''))
   counts[key]+=1
   if t=='event_msg' and d.get('type')=='item_completed':key='item:'+str(d.get('item',{}).get('type'))
   if (t=='event_msg' and d.get('type') in events) or t in {'turn_context','session_meta','compacted'}:
    candidate=d.get('item',{}) if key.startswith('item:') else d
    sig=json.dumps(shape(candidate),sort_keys=True)
    if key not in schemas:schemas[key]=collections.Counter()
    schemas[key][sig]+=1
    examples.setdefault(key,(str(p),n,candidate,d))
   if t=='event_msg' and d.get('type')=='item_completed':counts[key]+=1
print('FILES',len(files));print('\n'.join(files))
print('COUNTS',json.dumps(counts,sort_keys=True))
for key in sorted(schemas):
 print('\nSCHEMA',key)
 for sig,count in schemas[key].most_common(3):print(count,sig)
 p,n,x,d=examples[key];print('EXAMPLE',p+':'+str(n))
 if key.startswith('item:'):
  print('envelope_fields',sorted(d))
  safe={k:v for k,v in x.items() if k in {'type','status','exit_code','phase','kind','server','tool','success','summary_text','duration_ms'}}
  print('selected_values',json.dumps(safe,ensure_ascii=False)[:700])
